/**
 * 알림 메시지 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 *
 * mqpub 3.x는 한 배치 안에서 키의 앞 16바이트가 같은 메시지를 중복으로 보고 첫 것만 남긴다
 * (오류·경고 없음, accepted는 요청 건수 그대로). 같은 날짜·채널 주문은 규약 접두부가 같아
 * 서로 덮이므로, 키 맨 앞에 사건별 결정적 해시를 둔다. 같은 사건은 늘 같은 키다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  const head = createHash("sha1").update(logical).digest("hex").slice(0, 12);
  return `${head}:${logical}`;
}

